import React, { useState, useEffect, useRef } from 'react';
import './App.css';

function App() {
  // Data from backend
  const [customers, setCustomers] = useState([]);
  const [storages, setStorages] = useState([]);
  const [categories, setCatalogs] = useState([]);

  // Table: [{id, customerId, customerName, searchTerm, customerSuggestions, products: [{id, category, quantity, weight, storageId, storageName, storageSearch, storageSuggestions}]}]
  const [customerRows, setCustomerRows] = useState([]);

  // Fetch customers, storages, categories
  useEffect(() => {
    fetch("http://127.0.0.1:5000/customers")
      .then(res => res.json())
      .then(data => setCustomers(data.customers.map(c => ({
        id: c.CustomerID,
        name: c.CustomerName,
        address: c.CustomerAddress,
        location: [c.CustomerLat, c.CustomerLong],
      }))))
      .catch(console.error);

    fetch("http://127.0.0.1:5000/storages")
      .then(res => res.json())
      .then(data => setStorages(data.storages.map(s => ({
        id: s.StorageID,
        name: s.StorageName,
        address: s.StorageAddress,
        location: [s.StorageLat, s.StorageLong],
      }))))
      .catch(console.error);

    fetch("http://127.0.1:5000/catalogs")
      .then(res => res.json())
      .then(data => setCatalogs(data.catalogs.map(c => ({
        id: c.CatalogID,
        name: c.CatalogName,
      }))))
      .catch(console.error);
  }, []);

  // Add a new customer row
  const addCustomer = () => {
    setCustomerRows([
      ...customerRows,
      {
        id: Date.now() + Math.random(),
        customerId: '',
        customerName: '',
        searchTerm: '',
        customerSuggestions: [],
        products: [createEmptyProduct()]
      }
    ]);
  };

  // Add a new product row for a customer
  const addProduct = (custIdx) => {
    setCustomerRows(customerRows.map((cust, i) =>
      i === custIdx
        ? { ...cust, products: [...cust.products, createEmptyProduct()] }
        : cust
    ));
  };

  // Remove a customer
  const removeCustomer = (custIdx) => {
    setCustomerRows(customerRows.filter((_, i) => i !== custIdx));
  };

  // Remove a product from a customer
  const removeProduct = (custIdx, prodIdx) => {
    setCustomerRows(customerRows.map((cust, i) =>
      i === custIdx
        ? { ...cust, products: cust.products.filter((_, j) => j !== prodIdx) }
        : cust
    ));
  };

  // Update a customer field
  const updateCustomer = (custIdx, field, value) => {
    setCustomerRows(customerRows.map((cust, i) =>
      i === custIdx ? { ...cust, [field]: value } : cust
    ));
  };

  // Update a product field
  const updateProduct = (custIdx, prodIdx, field, value) => {
    setCustomerRows(customerRows.map((cust, i) =>
      i === custIdx
        ? {
            ...cust,
            products: cust.products.map((prod, j) =>
              j === prodIdx ? { ...prod, [field]: value } : prod
            )
          }
        : cust
    ));
  };

  // Live search for customer
  const handleCustomerSearch = (custIdx, value) => {
    updateCustomer(custIdx, 'searchTerm', value);
    const suggestions = value.trim()
      ? customers.filter(c =>
          c.name.toLowerCase().includes(value.toLowerCase()) &&
          !customerRows.some((row, i) => i !== custIdx && row.customerId === c.id)
        ).slice(0, 5)
      : [];
    updateCustomer(custIdx, 'customerSuggestions', suggestions);
    if (value === '') {
      updateCustomer(custIdx, 'customerName', '');
      updateCustomer(custIdx, 'customerId', '');
    } else {
      updateCustomer(custIdx, 'customerName', value);
      updateCustomer(custIdx, 'customerId', '');
    }
  };

  // Select a customer from suggestions
  const selectCustomer = (custIdx, customer) => {
    updateCustomer(custIdx, 'customerId', customer.id);
    updateCustomer(custIdx, 'customerName', customer.name);
    updateCustomer(custIdx, 'customerSuggestions', []);
    updateCustomer(custIdx, 'searchTerm', undefined);
  };

  // Live search for storage (per product)
  const handleStorageSearch = (custIdx, prodIdx, value) => {
    updateProduct(custIdx, prodIdx, 'storageSearch', value);
    const suggestions = value.trim()
      ? storages.filter(s =>
          s.name.toLowerCase().includes(value.toLowerCase()) &&
          !customerRows[custIdx].products.some((prod, j) => j !== prodIdx && prod.storageId === s.id)
        ).slice(0, 5)
      : [];
    updateProduct(custIdx, prodIdx, 'storageSuggestions', suggestions);
    if (value === '') {
      updateProduct(custIdx, prodIdx, 'storageName', '');
      updateProduct(custIdx, prodIdx, 'storageId', '');
    } else {
      updateProduct(custIdx, prodIdx, 'storageName', value);
      updateProduct(custIdx, prodIdx, 'storageId', '');
    }
  };

  // Select a storage from suggestions
  const selectStorage = (custIdx, prodIdx, storage) => {
    updateProduct(custIdx, prodIdx, 'storageId', storage.id);
    updateProduct(custIdx, prodIdx, 'storageName', storage.name);
    updateProduct(custIdx, prodIdx, 'storageSuggestions', []);
    updateProduct(custIdx, prodIdx, 'storageSearch', undefined);
  };

  // Helper to create an empty product row
  function createEmptyProduct() {
    return {
      id: Date.now() + Math.random(),
      category: '',
      quantity: '',
      weight: '',
      storageId: '',
      storageName: '',
      storageSearch: '',
      storageSuggestions: []
    };
  }

  // Add one customer row on mount
  useEffect(() => {
    if (customerRows.length === 0) addCustomer();
    // eslint-disable-next-line
  }, []);

  // Submit handler (placeholder)
  const handleSubmit = () => {
    console.log(customerRows);
  };

  return (
    <div className="container">
      <header className="header">
        <div className="header-left">
          <h1 className="route-name">Assign Truck</h1>
        </div>
        <div className="header-right">
          <button className="btn add-row-btn" onClick={addCustomer}>+ Add Customer</button>
        </div>
      </header>
      <div className="content">
        <main className="main-area">
          <div className="table">
            <div className="table-header">
              <span>Customer</span>
              <span>Category</span>
              <span>Quantity</span>
              <span>Weight</span>
              <span>Storage</span>
              <span></span>
            </div>
            {customerRows.map((cust, custIdx) => (
              <div className="customer-box" key={cust.id}>
                <div className="table-row">
                  {/* Customer live suggestion */}
                  <div className="table-cell">
                    <div className="suggestion-wrapper">
                      <input
                        className="input customer-input"
                        placeholder="Type to search customers…"
                        value={cust.searchTerm !== undefined ? cust.searchTerm : cust.customerName}
                        onChange={e => handleCustomerSearch(custIdx, e.target.value)}
                      />
                      {cust.customerSuggestions?.length > 0 && (
                        <ul className="suggestions-list">
                          {cust.customerSuggestions.map(c => (
                            <li key={c.id} onClick={() => selectCustomer(custIdx, c)}>
                              {c.name} — {c.address}
                            </li>
                          ))}
                        </ul>
                      )}
                    </div>
                  </div>
                  {/* Add/Remove customer button */}
                  <div className="remove-btn-cell">
                    <button className="btn remove-btn" onClick={() => removeCustomer(custIdx)}>×</button>
                  </div>
                </div>
                {/* Product rows for this customer */}
                {cust.products.map((prod, prodIdx) => (
                  <div className="table-row" key={prod.id}>
                    {/* Category dropdown */}
                    <div className="table-cell">
                      <select
                        className="input category-input"
                        value={prod.category}
                        onChange={e => updateProduct(custIdx, prodIdx, 'category', e.target.value)}
                      >
                        <option value="">Select Category</option>
                        {categories.map(c => (
                          <option key={c.id} value={c.id}>{c.name}</option>
                        ))}
                      </select>
                    </div>
                    {/* Quantity input */}
                    <div className="table-cell">
                      <input
                        className="input quantity-input"
                        type="string"
                        placeholder="Quantity"
                        value={prod.quantity}
                        onChange={e => updateProduct(custIdx, prodIdx, 'quantity', e.target.value)}
                      />
                    </div>
                    {/* Weight input */}
                    <div className="table-cell">
                      <input
                        className="input weight-input"
                        type="string"
                        placeholder="Weight"
                        value={prod.weight}
                        onChange={e => updateProduct(custIdx, prodIdx, 'weight', e.target.value)}
                      />
                    </div>
                    {/* Storage live suggestion */}
                    <div className="table-cell">
                      <div className="suggestion-wrapper">
                        <select
                          className="input storage-input"
                          value={prod.storageId}
                          onChange={e => updateProduct(custIdx, prodIdx, 'storageId', e.target.value)}
                        >
                          <option value="">Select Storage</option>
                          {storages.map(s => (
                            <option key={s.id} value={s.id}>{s.name}</option>
                          ))}
                        </select>
                        {/* Uncomment below for live search storage input */}
                        {/* <input
                          className="input storage-input"
                          placeholder="Type to search storages…"
                          value={prod.storageSearch !== undefined ? prod.storageSearch : prod.storageName}
                          onChange={e => handleStorageSearch(custIdx, prodIdx, e.target.value)}
                        />
                        {prod.storageSuggestions?.length > 0 && (
                          <ul className="suggestions-list">
                            {prod.storageSuggestions.map(s => (
                              <li key={s.id} onClick={() => selectStorage(custIdx, prodIdx, s)}>
                                {s.name} — {s.address}
                              </li>
                            ))}
                          </ul>
                        )} */}
                      </div>
                    </div>
                    {/* Remove product button */}
                    <div className="remove-btn-cell">
                      <button className="btn remove-btn" onClick={() => removeProduct(custIdx, prodIdx)}>×</button>
                    </div>
                  </div>
                ))}
                {/* Add Product button for this customer */}
                <div className="submit-btn-row">
                  <button className="btn add-row-btn" onClick={() => addProduct(custIdx)}>+ Add Product</button>
                </div>
              </div>
            ))}
          </div>
          <div className="submit-btn-row">
            <button className="btn submit-btn" onClick={handleSubmit}>Submit</button>
          </div>
        </main>
      </div>
    </div>
  );
}

export default App;
